  const scoredTasks: string[] = [];
  const common = {
    teacherOptions: options(ctx), numTrials: 1, sampleCount: 1,
    maxMetricCalls: 1, apply: false, verbose: false,
    bootstrap: { maxBootstrapMetricCalls: 1, maxBootstrapDemos: 3, scoreThreshold: 1 },
  } as const;
