    ...common, studentAI: unroutable.executor, teacherAI: unroutable.executor,
    metric: actionMetric,
    target: unroutable.assistant.namedPrograms().map(({ id }) => id),
  }), /Unknown program ID\(s\) in demos: stock-context\.actor/);
