    features: ['audio-stream', 'SSE', 'isDelta', 'pcm16', 'voice', 'transcript-deltas'], modes: ['offline'],
    async run(ctx) {
      let requests = 0;
      const llm = ai({ name: 'openai', apiKey: 'fixture-not-a-key', config: axAIOpenAIAudioDefaultConfig(),
        options: { fetch: async (_url, init) => {
          requests++;
